final class DropAddZero: SyntaxRewriter {
    override func visitAny(_ node: Syntax) -> Syntax? {
        guard let infix = node.as(InfixOperatorExprSyntax.self),
              let rhs = infix.rightOperand.as(IntegerLiteralExprSyntax.self),
              rhs.literal.text == "0" else { return nil }   // nil: keep walking
        return Syntax(infix.leftOperand)                    // x + 0 -> x
    }
}
